<?php
require_once __DIR__ . '/../config/db.php';
$pageTitle = 'Projects | Freelance Marketplace System';
$search=trim($_GET['search']??''); $filterStatus=trim($_GET['status']??''); $successMsg=$_GET['success']??''; $errorMsg=$_GET['error']??'';
$query="SELECT p.project_id,p.title,p.description,p.budget,p.date_posted,p.status,p.client_id,u.name AS client_name FROM Project p INNER JOIN Client c ON p.client_id=c.client_id INNER JOIN `User` u ON c.client_id=u.user_id WHERE 1=1"; $params=[]; $types='';
if($search!==''){ $query.=" AND (p.title LIKE ? OR p.description LIKE ? OR u.name LIKE ?)"; $like='%'.$search.'%'; $params=[$like,$like,$like]; $types.='sss'; }
if($filterStatus!==''){ $query.=" AND p.status = ?"; $params[]=$filterStatus; $types.='s'; }
$query.=" ORDER BY p.project_id"; if(count($params)>0){$stmt=$conn->prepare($query); $stmt->bind_param($types,...$params); $stmt->execute(); $projects=$stmt->get_result();} else {$projects=$conn->query($query);} include __DIR__ . '/../includes/header.php'; include __DIR__ . '/../includes/navbar.php';
?>
<section class="table-card"><div class="section-heading"><div><span class="eyebrow">Project Records</span><h2 class="page-title">Projects</h2><p class="page-intro">All posted projects with client information.</p></div><div class="section-actions"><a class="btn" href="<?php echo $basePath; ?>/pages/add_project.php">+ Add Project</a></div></div><?php if($successMsg!==''):?><div class="message success"><?php echo htmlspecialchars($successMsg); ?></div><?php endif;?><?php if($errorMsg!==''):?><div class="message error"><?php echo htmlspecialchars($errorMsg); ?></div><?php endif;?><form method="GET" action="" class="search-bar" style="display:flex;"><input type="text" name="search" placeholder="Search by title, description, or client..." value="<?php echo htmlspecialchars($search); ?>"><select name="status" style="max-width:160px;"><option value="">All Statuses</option><option value="Open" <?php echo $filterStatus === 'Open' ? 'selected' : ''; ?>>Open</option><option value="In Progress" <?php echo $filterStatus === 'In Progress' ? 'selected' : ''; ?>>In Progress</option><option value="Completed" <?php echo $filterStatus === 'Completed' ? 'selected' : ''; ?>>Completed</option></select><button type="submit" class="btn btn-secondary">Filter</button><?php if($search!==''||$filterStatus!==''):?><a href="<?php echo $basePath; ?>/pages/projects.php" class="btn btn-secondary">Clear</a><?php endif;?></form><div class="table-wrapper"><table><thead><tr><th>ID</th><th>Title</th><th>Budget</th><th>Status</th><th>Date Posted</th><th>Client</th><th>Actions</th></tr></thead><tbody><?php if($projects&&$projects->num_rows>0):?><?php while($row=$projects->fetch_assoc()):?><tr><td><?php echo $row['project_id']; ?></td><td><?php echo htmlspecialchars($row['title']); ?></td><td>$<?php echo number_format((float)$row['budget'],2); ?></td><td><span class="badge badge-<?php echo strtolower(str_replace(' ','',$row['status'])); ?>"><?php echo htmlspecialchars($row['status']); ?></span></td><td><?php echo htmlspecialchars($row['date_posted']); ?></td><td><?php echo htmlspecialchars($row['client_name']); ?> (ID: <?php echo $row['client_id']; ?>)</td><td><div class="btn-group"><a class="btn btn-sm" href="<?php echo $basePath; ?>/pages/project_details.php?project_id=<?php echo $row['project_id']; ?>">View</a><a class="btn btn-sm btn-secondary" href="<?php echo $basePath; ?>/pages/edit_project.php?id=<?php echo $row['project_id']; ?>">Edit</a><a class="btn btn-sm btn-danger" href="<?php echo $basePath; ?>/pages/delete_project.php?id=<?php echo $row['project_id']; ?>" onclick="return confirm('Are you sure you want to delete this project? This will also delete related proposals and contracts.');">Delete</a></div></td></tr><?php endwhile;?><?php else:?><tr><td colspan="7"><div class="empty-state"><p>No projects found.</p><a class="btn" href="<?php echo $basePath; ?>/pages/add_project.php">Add the first project</a></div></td></tr><?php endif;?></tbody></table></div></section><?php include __DIR__ . '/../includes/footer.php'; $conn->close(); ?>
